// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

contract MobileBackendRBAC {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    enum Role { NONE, USER, MODERATOR, ADMIN }

    struct Session {
        address user;
        Role role;
        uint256 nonce;
        uint256 expiresAt;
    }

    address public immutable signerAuthority;
    mapping(address => Role) public roles;
    mapping(bytes32 => bool) public usedSessionTokens;
    mapping(address => uint256) public userNonces;

    uint256 public constant SESSION_DURATION = 1 hours;
    bytes32 private constant DOMAIN_SEPARATOR_TYPEHASH = keccak256("EIP712Domain(string name,uint256 chainId,address verifyingContract)");
    bytes32 private constant SESSION_TYPEHASH = keccak256("Session(address user,uint8 role,uint256 nonce,uint256 expiresAt)");
    bytes32 private constant ACTION_TYPEHASH = keccak256("Action(address user,string action,bytes data,uint256 nonce)");

    event RoleGranted(address indexed user, Role role);
    event ActionExecuted(address indexed user, string action);
    event SessionCreated(address indexed user, bytes32 sessionId);

    modifier onlyAdmin() {
        require(roles[msg.sender] == Role.ADMIN, "Not admin");
        _;
    }

    constructor(address _signer) {
        signerAuthority = _signer;
        roles[msg.sender] = Role.ADMIN;
    }

    function grantRole(address user, Role role) external onlyAdmin {
        require(role != Role.NONE, "Cannot grant NONE");
        roles[user] = role;
        emit RoleGranted(user, role);
    }

    function getDomainSeparator() public view returns (bytes32) {
        return keccak256(abi.encode(
            DOMAIN_SEPARATOR_TYPEHASH,
            keccak256("MobileBackendRBAC"),
            block.chainid,
            address(this)
        ));
    }

    function createSession(address user, uint8 role, uint256 nonce, uint256 expiresAt, bytes memory signature) 
        external returns (bytes32 sessionId) 
    {
        require(expiresAt > block.timestamp, "Session expired");
        require(expiresAt <= block.timestamp + SESSION_DURATION, "Duration too long");
        require(nonce == userNonces[user], "Invalid nonce");
        require(Role(role) != Role.NONE, "Invalid role");
        require(roles[user] >= Role(role), "Insufficient role");

        bytes32 structHash = keccak256(abi.encode(
            SESSION_TYPEHASH, user, role, nonce, expiresAt
        ));
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", getDomainSeparator(), structHash));

        address recovered = digest.recover(signature);
        require(recovered == signerAuthority, "Invalid signature");

        sessionId = keccak256(abi.encode(user, nonce, expiresAt));
        require(!usedSessionTokens[sessionId], "Session already used");
        usedSessionTokens[sessionId] = true;
        userNonces[user] = nonce + 1;

        emit SessionCreated(user, sessionId);
        return sessionId;
    }

    function executeAction(
        address user, 
        string calldata action, 
        bytes calldata data, 
        uint256 nonce,
        bytes memory signature
    ) external returns (bool) {
        require(roles[user] >= Role.USER, "No role assigned");

        bytes32 structHash = keccak256(abi.encode(
            ACTION_TYPEHASH, user, keccak256(bytes(action)), keccak256(data), nonce
        ));
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", getDomainSeparator(), structHash));

        address recovered = digest.recover(signature);
        require(recovered == signerAuthority, "Invalid signature");

        emit ActionExecuted(user, action);
        return true;
    }

    function executePrivilegedAction(
        address user,
        string calldata action,
        bytes calldata data,
        uint256 nonce,
        bytes memory signature
    ) external returns (bool) {
        require(roles[user] >= Role.MODERATOR, "Insufficient privileges");

        bytes32 structHash = keccak256(abi.encode(
            ACTION_TYPEHASH, user, keccak256(bytes(action)), keccak256(data), nonce
        ));
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", getDomainSeparator(), structHash));

        address recovered = digest.recover(signature);
        require(recovered == signerAuthority, "Invalid signature");

        if (keccak256(bytes(action)) == keccak256("DELETE_USER")) {
            address target = abi.decode(data, (address));
            require(target != user, "Cannot delete self");
            roles[target] = Role.NONE;
        } else if (keccak256(bytes(action)) == keccak256("PROMOTE_USER")) {
            (address target, uint8 newRole) = abi.decode(data, (address, uint8));
            require(Role(newRole) < roles[user], "Cannot promote above own role");
            roles[target] = Role(newRole);
        }

        emit ActionExecuted(user, action);
        return true;
    }
}
